-- TwelveSpec proposed PostgreSQL 15+ schema. Review and test before migration.
create extension if not exists pgcrypto;
create schema if not exists app;
create table app.tenants(id uuid primary key default gen_random_uuid(), name text not null, created_at timestamptz not null default now());
create table app.workspaces(id uuid primary key default gen_random_uuid(), tenant_id uuid not null references app.tenants(id), name text not null, unique(id,tenant_id));
create table app.workspace_memberships(id uuid primary key default gen_random_uuid(), tenant_id uuid not null, workspace_id uuid not null, user_id uuid not null, role text not null check(role in ('owner','admin','catalog_manager','sales','operator','viewer')), foreign key(workspace_id,tenant_id) references app.workspaces(id,tenant_id), unique(workspace_id,user_id));
create table app.legal_entities(id uuid primary key default gen_random_uuid(), tenant_id uuid not null references app.tenants(id), legal_name text not null);
create table app.providers(id text primary key, label text not null, protocol text not null, is_enabled boolean not null default true);
create table app.provider_connections(id uuid primary key default gen_random_uuid(), tenant_id uuid not null, workspace_id uuid not null, provider_id text not null references app.providers(id), display_name text not null, environment text not null check(environment in ('mock','sandbox','production')), credential_reference text, status text not null default 'unverified', created_at timestamptz not null default now(), updated_at timestamptz not null default now(), foreign key(workspace_id,tenant_id) references app.workspaces(id,tenant_id), unique(id,tenant_id), check(credential_reference is null or length(credential_reference) < 512));
comment on column app.provider_connections.credential_reference is 'Server-only pointer to managed secret storage; NEVER plaintext key or token';
create table app.provider_capabilities(id uuid primary key default gen_random_uuid(), tenant_id uuid not null, connection_id uuid not null, capability text not null, service_version text, state text not null check(state in ('available','unsupported','credential_required','license_required','failed','unverified')), evidence_source text not null, tested_at timestamptz, foreign key(connection_id,tenant_id) references app.provider_connections(id,tenant_id), unique(connection_id,capability,service_version));
create table app.integration_endpoints(id uuid primary key default gen_random_uuid(), tenant_id uuid not null, connection_id uuid not null, capability text not null, service_version text, endpoint_url text not null, approval_status text not null default 'unverified', foreign key(connection_id,tenant_id) references app.provider_connections(id,tenant_id));
create table app.parties(id uuid primary key default gen_random_uuid(), tenant_id uuid not null, workspace_id uuid not null, kind text not null check(kind in ('customer','supplier','decorator','broker','other')), name text not null, foreign key(workspace_id,tenant_id) references app.workspaces(id,tenant_id));
create table app.products(id uuid primary key default gen_random_uuid(), tenant_id uuid not null, workspace_id uuid not null, sku text not null, name text not null, description text not null default '', publish_state text not null default 'draft' check(publish_state in ('draft','staged','needs_review','validated','approved','published','retired')), current_revision integer not null default 1, created_at timestamptz not null default now(), foreign key(workspace_id,tenant_id) references app.workspaces(id,tenant_id), unique(workspace_id,sku), unique(id,tenant_id));
create table app.product_variants(id uuid primary key default gen_random_uuid(), tenant_id uuid not null, product_id uuid not null, sku text not null, attributes jsonb not null default '{}'::jsonb, foreign key(product_id,tenant_id) references app.products(id,tenant_id), unique(product_id,sku));
create table app.supplier_offers(id uuid primary key default gen_random_uuid(), tenant_id uuid not null, variant_id uuid not null references app.product_variants(id), supplier_connection_id uuid not null, source_sku text not null, currency char(3) not null default 'USD', base_cost numeric(18,4), minimum_quantity integer, provenance jsonb not null default '{}'::jsonb, observed_at timestamptz, foreign key(supplier_connection_id,tenant_id) references app.provider_connections(id,tenant_id), check(base_cost is null or base_cost >= 0));
create table app.import_batches(id uuid primary key default gen_random_uuid(), tenant_id uuid not null, workspace_id uuid not null, connection_id uuid, source_hash text not null, input_format text not null check(input_format in ('csv','xml','api')), state text not null default 'staged', mapping jsonb not null default '{}'::jsonb, created_at timestamptz not null default now(), foreign key(workspace_id,tenant_id) references app.workspaces(id,tenant_id), foreign key(connection_id,tenant_id) references app.provider_connections(id,tenant_id));
create table app.import_rows(id uuid primary key default gen_random_uuid(), batch_id uuid not null references app.import_batches(id), source_row integer not null, raw jsonb not null, normalized jsonb, errors jsonb not null default '[]'::jsonb, decision text not null default 'staged');
create table app.artwork_projects(id uuid primary key default gen_random_uuid(), tenant_id uuid not null, workspace_id uuid not null, customer_id uuid, status text not null default 'uploaded', foreign key(workspace_id,tenant_id) references app.workspaces(id,tenant_id));
create table app.artwork_versions(id uuid primary key default gen_random_uuid(), project_id uuid not null references app.artwork_projects(id), version integer not null, asset_reference text not null, sha256 text not null, approval_state text not null default 'draft', created_at timestamptz not null default now(), unique(project_id,version));
create table app.quotes(id uuid primary key default gen_random_uuid(), tenant_id uuid not null, workspace_id uuid not null, customer_id uuid not null references app.parties(id), status text not null default 'draft', created_at timestamptz not null default now(), foreign key(workspace_id,tenant_id) references app.workspaces(id,tenant_id));
create table app.quote_revisions(id uuid primary key default gen_random_uuid(), quote_id uuid not null references app.quotes(id), version integer not null, currency char(3) not null, pricing_snapshot jsonb not null, legal_seller_snapshot jsonb not null, issued_at timestamptz, unique(quote_id,version));
create table app.orders(id uuid primary key default gen_random_uuid(), tenant_id uuid not null, workspace_id uuid not null, accepted_revision_id uuid not null references app.quote_revisions(id), status text not null default 'awaiting_payment', created_at timestamptz not null default now(), foreign key(workspace_id,tenant_id) references app.workspaces(id,tenant_id));
create table app.jobs(id uuid primary key default gen_random_uuid(), tenant_id uuid not null, order_id uuid not null references app.orders(id), state text not null default 'planned', details jsonb not null default '{}'::jsonb);
create table app.purchase_orders(id uuid primary key default gen_random_uuid(), tenant_id uuid not null, order_id uuid not null references app.orders(id), provider_connection_id uuid not null references app.provider_connections(id), state text not null default 'draft', idempotency_key text not null, external_reference text, unique(tenant_id,provider_connection_id,idempotency_key));
create table app.shipments(id uuid primary key default gen_random_uuid(), tenant_id uuid not null, order_id uuid not null references app.orders(id), provider text, tracking_reference text, status text not null default 'pending');
create table app.outbox_events(id uuid primary key default gen_random_uuid(), tenant_id uuid not null, kind text not null, aggregate_id uuid not null, payload jsonb not null, status text not null default 'pending', attempts int not null default 0, created_at timestamptz not null default now());
create table app.audit_events(id bigserial primary key, tenant_id uuid not null, workspace_id uuid, actor_id uuid, action text not null, target_type text not null, target_id text, metadata jsonb not null default '{}'::jsonb, created_at timestamptz not null default now());
create index on app.products(tenant_id,workspace_id,publish_state);
create index on app.provider_connections(tenant_id,workspace_id);
create index on app.import_batches(tenant_id,workspace_id,created_at desc);
create index on app.outbox_events(status,created_at);
